<?php
session_start();require_once('dbstring.php');require_once('check-login.php');require_once('early-years-utils.php');eya_ensure_tables($con);$studentId=trim((string)($_GET['studentid']??''));$batchId=trim((string)($_GET['batchid']??''));$term=(int)($_GET['term']??0);if(!eya_admin()&&!class_teacher_can_manage_student_batch($con,(string)$_SESSION['USERID'],$studentId,$batchId,$term)){http_response_code(403);exit('You do not have permission to view this pupil report.');}$student=null;if($studentId!==''){$stmt=mysqli_prepare($con,"SELECT su.*,ce.class_name FROM tblsystemuser su LEFT JOIN tblclass cl ON cl.userid=su.userid AND cl.batchid=? AND cl.status='active' LEFT JOIN tblclassentry ce ON ce.class_entryid=cl.class_entryid WHERE su.userid=? AND su.systemtype='Student' LIMIT 1");mysqli_stmt_bind_param($stmt,'ss',$batchId,$studentId);mysqli_stmt_execute($stmt);$r=mysqli_stmt_get_result($stmt);$student=$r?mysqli_fetch_assoc($r):null;mysqli_stmt_close($stmt);}$rows=$student?mysqli_query($con,"SELECT s.category,s.skillname,a.rating,a.teachercomment FROM tblearlyyearsskill s LEFT JOIN tblearlyyearsassessment a ON a.skillid=s.skillid AND a.userid='".mysqli_real_escape_string($con,$studentId)."' AND a.batchid='".mysqli_real_escape_string($con,$batchId)."' AND a.termname=$term WHERE s.status='active' ORDER BY s.display_order"):null;$labels=array(1=>'Beginning',2=>'Developing',3=>'Secure',4=>'Excelling');?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Early Years Progress Report</title><style>body{font:15px Arial;color:#183650;margin:0;background:#f3f7fa}.wrap{max-width:850px;margin:32px auto;padding:0 18px}.report{background:#fff;border:1px solid #d7e2ea;border-radius:14px;padding:28px}.head{border-bottom:3px solid #08766f;padding-bottom:15px}h1{font:600 30px Georgia;margin:4px 0}table{width:100%;border-collapse:collapse;margin-top:18px}th,td{text-align:left;padding:11px;border-bottom:1px solid #e2eaf0}th{background:#f2f7f8}.rating{font-weight:bold;color:#08766f}.print{display:inline-block;margin:16px 0;padding:10px 13px;border:0;border-radius:7px;background:#08766f;color:#fff;text-decoration:none}@media print{body{background:#fff}.print{display:none}.wrap{margin:0;max-width:none}}</style></head><body><main class="wrap"><a class="print" href="#" onclick="window.print();return false;">Print report</a><section class="report"><?php if(!$student){?><p>Select a valid pupil, batch, and term from the assessment area.</p><?php }else{$name=trim($student['firstname'].' '.$student['othernames'].' '.$student['surname']);?><div class="head"><small>AWUAH PREPARATORY SCHOOL</small><h1>Early Years Progress Report</h1><p><b>Pupil:</b> <?php echo eya_safe($name);?> &nbsp; <b>Class:</b> <?php echo eya_safe($student['class_name']);?> &nbsp; <b>Term:</b> <?php echo $term;?></p><p>Rating guide: Beginning · Developing · Secure · Excelling</p></div><table><thead><tr><th>Learning area</th><th>Skill</th><th>Progress</th><th>Teacher comment</th></tr></thead><tbody><?php while($rows&&($row=mysqli_fetch_assoc($rows))){?><tr><td><?php echo eya_safe($row['category']);?></td><td><?php echo eya_safe($row['skillname']);?></td><td class="rating"><?php echo isset($labels[$row['rating']])?eya_safe($labels[$row['rating']]):'Not assessed';?></td><td><?php echo eya_safe($row['teachercomment']);?></td></tr><?php }?></tbody></table><?php }?></section></main></body></html>
